import{_ as s,C as e,o,c as n,a2 as r,E as i}from"./chunks/framework.Dkj3JE0_.js";const u=JSON.parse('{"title":"学習ベース","description":"","frontmatter":{"title":"学習ベース"},"headers":[],"relativePath":"jp/blogs/0-start.md","filePath":"jp/blogs/0-start.md"}'),l={name:"jp/blogs/0-start.md"};function c(d,a,p,_,h,g){const t=e("NoteIndex");return o(),n("div",null,[a[0]||(a[0]=r('<h1 id="学習ベース" tabindex="-1">学習ベース <a class="header-anchor" href="#学習ベース" aria-label="Permalink to &quot;学習ベース&quot;">​</a></h1><p>理解し、覚え、使えるようにしたい概念を集めた作業用のライブラリです。体系的な学習計画、トピック別ノート、例題、図解、実装演習をまとめています。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>これは常に更新中の学習ノートであり、決定版の参考資料ではありません。理解が深まるたびに見直しています。正確さが必要な場面では、公式カリキュラムや一次資料を参照してください。</p></div><h2 id="ここから始める" tabindex="-1">ここから始める <a class="header-anchor" href="#ここから始める" aria-label="Permalink to &quot;ここから始める&quot;">​</a></h2><p>今日必要なものに合わせてトラックを選んでください。</p><div class="learning-directory"><a class="directory-card directory-card--primary" href="/jp/blogs/CFA/plan"><span class="directory-card__number">01 · CFA レベル II</span><strong>CFA ノートを始める</strong><span class="directory-card__description">11 月 18 日の試験に向けた集中プラン（10 月は FSA 優先、11 月は模試）。計画を開き、「次のページ」からカリキュラム順に進めます。</span><span class="directory-card__action">計画を開く <b>→</b></span></a><a class="directory-card" href="/jp/blogs/JLPT-N2/plan"><span class="directory-card__number">02 · JLPT N2</span><strong>日本語の学習計画</strong><span class="directory-card__description">11 月中旬まで 1 日 2 時間が上限（試験は 12 月 6 日）：語彙、動画、文法、ローテーション演習。</span><span class="directory-card__action">計画を見る <b>↗</b></span></a><a class="directory-card" href="/jp/blogs/German/plan"><span class="directory-card__number">03 · ビジネスドイツ語</span><strong>ドイツ語の学習計画</strong><span class="directory-card__description">会議、プレゼンテーション、ビジネス文書のための実践的なコミュニケーション。</span><span class="directory-card__action">計画を見る <b>↗</b></span></a></div><h2 id="cfa-level-ii-directory" tabindex="-1">CFA レベル II 目次 <a class="header-anchor" href="#cfa-level-ii-directory" aria-label="Permalink to &quot;CFA レベル II 目次 {#cfa-level-ii-directory}&quot;">​</a></h2><p>トピックはカリキュラムの順に並んでいます。各ノートは前後のモジュールにリンクしているので、通して読むことも、下から直接開くこともできます。ノートは英語の原稿を翻訳したもので、食い違いがある場合は英語版が正です。</p>',8)),i(t),a[1]||(a[1]=r('<h2 id="応用した仕事" tabindex="-1">応用した仕事 <a class="header-anchor" href="#応用した仕事" aria-label="Permalink to &quot;応用した仕事&quot;">​</a></h2><ul><li><a href="/jp/projects/NCCP.html">プロジェクト</a>——このノートのテーマにつながる研究と実装の仕事。</li></ul><h2 id="ノートの使い方" tabindex="-1">ノートの使い方 <a class="header-anchor" href="#ノートの使い方" aria-label="Permalink to &quot;ノートの使い方&quot;">​</a></h2><ol><li><strong>計画：</strong> 該当する学習計画から、その週に達成することを決める。</li><li><strong>学習：</strong> モジュールを読み、ノートを見ずに要点を言い直す。</li><li><strong>応用：</strong> 計算、問題、コード、または短い実務タスクに取り組む。</li><li><strong>診断：</strong> 間違った答えや失敗した実装が、なぜそのときは正しく見えたのかを記録する。</li><li><strong>復習：</strong> 難しかった内容を 2 日後、1 週間後、3 週間後に見直す。</li></ol><p>目的はページを増やすことではありません。概念を思い出す、判断を下す、問題を解く——そのどれかに役立つとき、ノートは価値を持ちます。</p><h2 id="ノートの約束事" tabindex="-1">ノートの約束事 <a class="header-anchor" href="#ノートの約束事" aria-label="Permalink to &quot;ノートの約束事&quot;">​</a></h2><ul><li><strong>Important</strong> の囲みは、混同しやすい違いを示します。</li><li><strong>Exam focus</strong> の節は、CFA で問われやすい内容を優先します。</li><li><strong>For understanding</strong> の節は、シラバスを超えた直感的な理解を説明します。</li><li>例題では、結果を解釈する前に計算の構造を示します。</li><li>インタラクティブなグラフやコード例は補助です。主な学びは文章で書いた結論です。</li></ul><p>サイドバーからアーカイブ全体を閲覧するか、次の学習方針を決めたいときにここへ戻ってきてください。</p>',8))])}const m=s(l,[["render",c]]);export{u as __pageData,m as default};
